}

}  // namespace vllm

void swap_blocks(torch::Tensor& src, torch::Tensor& dst,
                 const torch::Tensor& block_mapping) {
  torch::Device src_device = src.device();
  torch::Device dst_device = dst.device();
  cudaMemcpyKind memcpy_type;
  if (src_device.is_cuda() && dst_device.is_cuda()) {
    TORCH_CHECK(src_device.index() == dst_device.index(),
                "src and dst must be on the same GPU");
    memcpy_type = cudaMemcpyDeviceToDevice;
  } else if (src_device.is_cuda() && dst_device.is_cpu()) {
    memcpy_type = cudaMemcpyDeviceToHost;
  } else if (src_device.is_cpu() && dst_device.is_cuda()) {
    memcpy_type = cudaMemcpyHostToDevice;
  } else {
    TORCH_CHECK(false, "Invalid device combination");
  }

  // NOTE(youkaichao): keep in mind that `block_mapping` should be
  // a cpu tensor, otherwise every `item` call will require a gpu-cpu
  // synchronization.
  TORCH_CHECK(block_mapping.device().is_cpu(), "block_mapping must be on CPU");

  char* src_ptr = static_cast<char*>(src.data_ptr());
  char* dst_ptr = static_cast<char*>(dst.data_ptr());

  const int64_t block_size_in_bytes = src.element_size() * src[0].numel();
  const at::cuda::OptionalCUDAGuard device_guard(
      src_device.is_cuda() ? src_device : dst_device);
  const cudaStream_t stream = at::cuda::getCurrentCUDAStream();
  const int64_t num_pairs = block_mapping.size(0);

  // Move block_mapping to the GPU to avoid per-element CPU-GPU synchronization
  torch::Tensor block_mapping_tensor =
      torch::from_blob(block_mapping.data_ptr<int64_t>(), {num_pairs * 2},
                       torch::kInt64)
          .to(src_device.is_cuda() ? src_device : dst_device);

  // Launch the kernel.
  dim3 grid(num_pairs);
  dim3 block(1);
  vllm::swap_blocks_kernel<<<grid, block, 0, stream>>>(
      block_mapping_tensor.data_ptr<int64_t>(), src_ptr, dst_ptr,
      block_size_in_bytes, memcpy_type, stream);
}

